edges = [(0,2),(0,4),(0,5),(1,2),(1,4),(1,5),(2,3),(3,4),(3,5)]

# Check triangle-free
n = 6
adj = [[False]*n for _ in range(n)]
for u,v in edges:
    adj[u][v] = True
    adj[v][u] = True

triangles = []
for i in range(n):
    for j in range(i+1,n):
        for k in range(j+1,n):
            if adj[i][j] and adj[j][k] and adj[i][k]:
                triangles.append((i,j,k))
print("Triangles:", triangles)

# Check maximal: for every non-edge, adding it creates a triangle
non_edges = []
for u in range(n):
    for v in range(u+1,n):
        if not adj[u][v]:
            non_edges.append((u,v))
print("Non-edges:", non_edges)

maximal = True
for u,v in non_edges:
    # check if there exists w such that both u-w and v-w are edges
    creates = False
    for w in range(n):
        if w!=u and w!=v and adj[u][w] and adj[v][w]:
            creates = True
            break
    if not creates:
        print(f"Adding ({u},{v}) does NOT create a triangle")
        maximal = False
print("Maximal:", maximal)
